// Parity of the "ace" area with Python, site services (swg3.web) included, in Portuguese and English.
// Vectors generated by tools/parity/ace.py (uv run python tools/gen_parity_vectors.py ace).
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, test } from "vitest";
import { setLang, type Lang } from "../src/i18n";
import * as badwords from "../src/lib/gen3/badwords";
import * as base64box from "../src/lib/gen3/base64box";
import * as boxnames from "../src/lib/gen3/boxnames";
import * as wild from "../src/lib/gen3/wild";
import * as builder from "../src/lib/gen3/builder";
import * as codeplan from "../src/lib/gen3/codeplan";
import { Pk3 } from "../src/lib/gen3/pk3";
import * as species from "../src/lib/gen3/species";
import { toHex } from "../src/lib/pyfmt";
import * as recipe from "../src/lib/recipe";
import * as svc from "../src/lib/services/pokemon";

type Json = Record<string, unknown>;
type Reply = { ok: true; result: unknown } | { ok: false; error: string };
type Both = { pt: Reply; en?: Reply };
interface BuildCase extends Both { fields: builder.BuildFields; base: string | null; seed: number | null }

interface Vectors {
  badwords: { boundary: string[]; strong: string[]; classify: [string, string, string, string][]; matches: [string, string[]][]; is_boundary: [string, boolean][] };
  boxnames: {
    keys: [string, boxnames.Key | null][];
    encode_name: [string, string][];
    parse_names: [string, Both][];
    parse_raw: [string, Both][];
    check_names: [string[], Both][];
    check_raw: [string, Both][];
    typing_steps: [string, Both][];
    press: [[number, number, number, number], boxnames.Move, [number, number, number, number]][];
  };
  base64box: {
    encode: [string, boolean, number[], base64box.EncodedDict][];
    errors: [string, boolean, number[], Both][];
    decode: [string[], string][];
    decode_cases: [string[], Both][];
    is_code: [string[], boolean][];
  };
  builder: {
    initial_moves: [number, number, number[]][];
    explicit: BuildCase[];
    seeded: BuildCase[];
    edits: BuildCase[];
    errors: BuildCase[];
    properties: { fields: builder.BuildFields; want: Record<string, unknown>; got: Json }[];
    choose_pid: (Both & { species: number; tid: number; sid: number; want: builder.PidWanted; seed: number })[];
    streams: { seed: number; bits16: number[] }[];
  };
  codeplan: (Both & { data: string; strategy: unknown })[];
  recipe: {
    trade: (Both & { data: string; game: unknown; save_as: string | null })[];
    load: (Both & { text: string; json_error: boolean })[];
  };
  services: [name: string, params: Json, lang: Lang, reply: Reply, jsonError: boolean][];
}

const V = JSON.parse(readFileSync(join(__dirname, "vectors", "ace.json"), "utf8")) as Vectors;
const NOW = new Date(Date.UTC(2026, 8, 29, 12, 0));

const bytes = (hex: string) => Uint8Array.from(hex.match(/../g) ?? [], (b) => parseInt(b, 16));
/** Like Python's JSON: no undefined fields. */
const plain = (value: unknown) => (value === undefined ? undefined : JSON.parse(JSON.stringify(value)));

function run(lang: Lang, fn: () => unknown): Reply {
  setLang(lang);
  try {
    return { ok: true, result: plain(fn()) };
  } catch (error) {
    return { ok: false, error: (error as Error).message };
  } finally {
    setLang("pt");
  }
}

function expectBoth(vector: Both, fn: () => unknown, label: string) {
  expect(run("pt", fn), label).toEqual(vector.pt);
  if (vector.en) expect(run("en", fn), `${label} (en)`).toEqual(vector.en);
}

describe("badwords", () => {
  test("terms and classification", () => {
    const [boundary, strong] = badwords.terms();
    expect([...boundary].sort(badwords.compareCodePoints)).toEqual(V.badwords.boundary);
    expect([...strong].sort(badwords.compareCodePoints)).toEqual(V.badwords.strong);
    for (const [pattern, term, kind, cls] of V.badwords.classify) {
      expect(badwords.parsePattern(pattern), pattern).toEqual([term, kind]);
      expect(badwords.classify(pattern)[1], pattern).toBe(cls);
    }
    for (const [term, value] of V.badwords.is_boundary) expect(badwords.isBoundary(term), term).toBe(value);
  });

  test("matches, with the cases confirmed on the Switch", () => {
    for (const [text, found] of V.badwords.matches) expect(badwords.matches(text), text).toEqual(found);
    expect(badwords.matches("Rx5XxlIk")).toContain("xxx");
    expect([badwords.blocked("bj"), badwords.blocked("ebj"), badwords.blocked("a s s"), badwords.blocked("mass")]).toEqual([true, false, true, false]);
  });
});

describe("boxnames", () => {
  test("keyboard and bytes", () => {
    for (const [char, key] of V.boxnames.keys) expect(boxnames.keyOf(char), char).toEqual(key);
    for (const [char, hex] of V.boxnames.encode_name) expect(toHex(boxnames.encodeName(char)), char).toBe(hex);
  });

  test("parseNames and parseRaw", () => {
    for (const [text, vector] of V.boxnames.parse_names) {
      // JSON syntax error: the detail comes from the parser, so only the start of the message is compared.
      if (!vector.pt.ok && vector.pt.error.includes("JSON")) {
        for (const lang of ["pt", "en"] as const) {
          const got = run(lang, () => boxnames.parseNames(text));
          const want = vector[lang] as { error: string };
          expect(got.ok, text).toBe(false);
          expect((got as { error: string }).error.split(":")[0], text).toBe(want.error.split(":")[0]);
        }
        continue;
      }
      expectBoth(vector, () => boxnames.parseNames(text), text);
    }
    for (const [text, vector] of V.boxnames.parse_raw) expectBoth(vector, () => toHex(boxnames.parseRaw(text)), text);
  });

  test("checkNames", () => {
    for (const [names, vector] of V.boxnames.check_names) {
      expectBoth(vector, () => {
        const [boxes, general] = boxnames.checkNames(names);
        return { boxes: boxes.map((b) => ({ number: b.number, name: b.name, raw: toHex(b.raw), issues: b.issues })), general };
      }, JSON.stringify(names));
    }
  });

  test("checkRaw with every error", () => {
    for (const [hex, vector] of V.boxnames.check_raw) expectBoth(vector, () => boxnames.checkRaw(bytes(hex)), hex);
  });

  test("typingSteps", () => {
    for (const [text, vector] of V.boxnames.typing_steps) expectBoth(vector, () => boxnames.typingSteps(text), text);
  });

  test("press", () => {
    expect(V.boxnames.press.length).toBeGreaterThan(0);
    for (const [cursor, key, expected] of V.boxnames.press) expect(boxnames.press(cursor, key), `${cursor} ${key}`).toEqual(expected);
  });
});

describe("base64box", () => {
  test("encode with and without Switch mode, and manual conversion", () => {
    for (const [hex, switchSafe, convert, want] of V.base64box.encode) {
      expect(base64box.encode(bytes(hex), switchSafe, convert).asDict(), `${hex} ${switchSafe} ${convert}`).toEqual(want);
    }
    for (const [hex, switchSafe, convert, vector] of V.base64box.errors) {
      expectBoth(vector, () => base64box.encode(bytes(hex), switchSafe, convert).asDict(), `${hex} ${convert}`);
    }
  });

  test("vectors from tests/test_base64box.py", () => {
    const zero = new Uint8Array(80);
    const converted = base64box.encode(zero, true, [5]);
    expect(converted.asDict().manual).toEqual({ 5: 4 });
    expect(converted.boxes[4]).toBe(".P.A.P.A");
    const xxx = base64box.encode(bytes(toHex(Uint8Array.from(atob("Rx5XxlIk"), (c) => c.charCodeAt(0))) + "00".repeat(74)));
    expect(xxx.boxes[0]).toBe("Rx5X");
  });

  test("decode and isBase64Code", () => {
    for (const [boxes, hex] of V.base64box.decode) expect(toHex(base64box.decode(boxes)), boxes.join("|")).toBe(hex);
    for (const [boxes, vector] of V.base64box.decode_cases) expectBoth(vector, () => toHex(base64box.decode(boxes)), boxes.join("|"));
    for (const [boxes, value] of V.base64box.is_code) expect(base64box.isBase64Code(boxes), boxes.join("|")).toBe(value);
  });
});

describe("builder", () => {
  test("pythonRandom reproduces random.Random(seed).getrandbits(16)", () => {
    for (const s of V.builder.streams) {
      const random = builder.pythonRandom(s.seed);
      expect(s.bits16.map(() => random()), String(s.seed)).toEqual(s.bits16);
    }
  });

  test("initialMoves", () => {
    for (const [s, level, moves] of V.builder.initial_moves) expect(builder.initialMoves(s, level), `${s} ${level}`).toEqual(moves);
  });

  const runBuild = (v: BuildCase) => () => {
    const [mon, notes] = builder.build(v.fields, v.base ? new Pk3(bytes(v.base)) : null, v.seed !== null ? builder.pythonRandom(v.seed) : builder.systemRandom());
    return { data: toHex(mon.data), notes };
  };

  test("explicit PID, draw with the Python seed, editing and errors", () => {
    for (const group of [V.builder.explicit, V.builder.seeded, V.builder.edits, V.builder.errors]) {
      for (const v of group) expectBoth(v, runBuild(v), JSON.stringify([v.fields, v.seed]));
    }
  });

  test("any generator: PID with the requested properties", () => {
    for (const v of V.builder.properties) {
      const [mon] = builder.build(v.fields, null, builder.systemRandom());
      const pid = mon.personality;
      const got: Json = {
        nature: pid % 25, shiny: mon.isShiny, gender: species.gender(mon.species, pid), ability: mon.abilityNum, letter: wild.unownLetter(pid),
      };
      for (const [key, value] of Object.entries(v.want)) {
        if (key === "letter" && mon.species !== wild.UNOWN) continue;
        if (key === "ability" && !species.info(mon.species).abilities[1]) continue;
        expect(got[key], `${JSON.stringify(v.fields)} ${key}`).toBe(value);
        expect(v.got[key]).toBe(value);
      }
      expect([mon.species, species.monLevel(mon)]).toEqual([v.fields.species, v.fields.level]);
      if (v.fields.ivs) expect(mon.ivs).toEqual(v.fields.ivs);
    }
  });

  test("choosePid", () => {
    for (const v of V.builder.choose_pid) {
      expectBoth(v, () => builder.choosePid(v.species, v.tid, v.sid, v.want, builder.pythonRandom(v.seed)), JSON.stringify(v));
    }
  });
});

describe("codeplan", () => {
  test("wild and egg strategies", () => {
    for (const v of V.codeplan) expectBoth(v, () => codeplan.plan(new Pk3(bytes(v.data)), v.strategy), `${v.data} ${v.strategy}`);
  });
});

describe("recipe", () => {
  test("trade with a fixed date", () => {
    for (const v of V.recipe.trade) expectBoth(v, () => recipe.trade(new Pk3(bytes(v.data)), v.game, v.save_as, NOW), v.data);
  });

  test("load and its errors", () => {
    for (const v of V.recipe.load) {
      const fn = () => {
        const [data, mon] = recipe.load(v.text);
        return { recipe: data, mon: toHex(mon.data) };
      };
      if (v.json_error) {
        for (const lang of ["pt", "en"] as const) {
          const got = run(lang, fn), want = v[lang] as { error: string };
          expect(got.ok, v.text).toBe(false);
          expect((got as { error: string }).error.split(":")[0], v.text).toBe(want.error.split(":")[0]);
        }
        continue;
      }
      expectBoth(v, fn, v.text);
    }
  });
});

const SERVICES: Record<string, (params: Json) => unknown> = {
  pk3_inspect: svc.pk3Inspect,
  lists: svc.lists,
  species_info: svc.speciesInfo,
  pk3_build: (params) => svc.pk3Build(params),
  code_plan: svc.codePlan,
  recipe_trade: (params) => svc.recipeTrade(params, NOW),
  recipe_check: svc.recipeCheck,
  box_names: svc.boxNames,
  base64_boxes: svc.base64Boxes,
};

function call(name: string, params: Json, lang: Lang): Reply {
  const reply = run(lang, () => SERVICES[name](params));
  if (!reply.ok) return { ok: false, error: reply.error };
  if (name === "recipe_trade") (reply.result as Json).created = null;
  return reply;
}

describe("services (web.py)", () => {
  test("full responses equal to Python's", () => {
    const counts: Record<string, number> = {};
    for (const [name, params, lang, want, jsonError] of V.services) {
      counts[name] = (counts[name] ?? 0) + 1;
      const got = call(name, params, lang);
      const label = `${name} ${lang} ${JSON.stringify(params).slice(0, 200)}`;
      if (jsonError) {
        expect(got.ok, label).toBe(false);
        expect((got as { error: string }).error.split(":")[0], label).toBe((want as { error: string }).error.split(":")[0]);
        continue;
      }
      expect(got, label).toEqual(want);
    }
    expect(Object.keys(counts).sort()).toEqual(Object.keys(SERVICES).sort());
  });

  test("ParamError on parameters", () => {
    expect(() => svc.pk3Inspect({ hex: "xyz" })).toThrow(svc.ParamError);
    expect(() => svc.speciesInfo({})).toThrow(svc.ParamError);
    // A rule error (ValueError in Python) is not a ParamError.
    const error = run("pt", () => svc.pk3Build({ fields: { species: 1, level: 5 } }));
    expect(error.ok).toBe(false);
    try {
      svc.pk3Build({ fields: { species: 1, level: 5 } });
    } catch (e) {
      expect(e).not.toBeInstanceOf(svc.ParamError);
    }
  });
});
